import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './App.css';

// Server URL for backend
const SERVER_URL = 'http://localhost:3001';

// Placeholder image for browser preview
const PLACEHOLDER_IMAGE = 'data:image/png;base64,';

/**
 * Simplified OpenAI MCP Client
 */
function App() {
    // Core state
    const [sessionId, setSessionId] = useState(null);
    const [messages, setMessages] = useState([]);
    const [inputValue, setInputValue] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);

    // Preview state
    const [browserImage, setBrowserImage] = useState(PLACEHOLDER_IMAGE);
    const [previewVisible, setPreviewVisible] = useState(true);
    const [streaming, setStreaming] = useState(false);
    const [streamStatus, setStreamStatus] = useState('waiting');

    // Status and technical details
    const [statusMessages, setStatusMessages] = useState([{
        type: 'info',
        text: 'Starting session...',
        time: new Date().toLocaleTimeString()
    }]);
    const [showTechnicalMessages, setShowTechnicalMessages] = useState(true);

    // Refs
    const messagesEndRef = useRef(null);
    const streamSourceRef = useRef(null);
    const messagePollingRef = useRef(null);
    const pollTimeoutRef = useRef(null);

    // Constants
    const POLL_INTERVAL = 3000; // 3 seconds between polls
    const MAX_POLLS = 60; // Maximum number of polling attempts (3 minutes)
    const POLL_THROTTLE = 1000; // Minimum time between polls (1 second)

    // Add a ref to track current messages to avoid closure issues
    const messagesRef = useRef(messages);

    // Keep messagesRef updated when messages change
    useEffect(() => {
        messagesRef.current = messages;
    }, [messages]);

    // Add a ref to track loading state to avoid closure issues
    const loadingRef = useRef(loading);

    // Keep loadingRef updated when loading changes
    useEffect(() => {
        loadingRef.current = loading;
    }, [loading]);

    /**
     * Add a status message with timestamp
     */
    const addStatusMessage = (type, text) => {
        const timeString = new Date().toLocaleTimeString();
        setStatusMessages(prev => {
            const newMessages = [...prev, { type, text, time: timeString }];
            // Keep only the most recent 10 messages
            return newMessages.length > 10 ? newMessages.slice(-10) : newMessages;
        });
    };

    /**
     * Check server health
     */
    const checkServerHealth = async () => {
        console.log('Checking server health...');
        try {
            const response = await axios.get(`${SERVER_URL}/health?_t=${Date.now()}`, {
                timeout: 5000
            });

            console.log('Health check response:', response.data);

            if (response.data && response.data.success) {
                addStatusMessage('success', 'Server connection verified');
                return true;
            } else {
                addStatusMessage('warning', 'Server health check returned unexpected response');
                return false;
            }
        } catch (err) {
            console.error('Server health check failed:', err);
            addStatusMessage('error', `Server connection error: ${err.message}`);
            return false;
        }
    };

    /**
     * Initialize session on component mount
     */
    useEffect(() => {
        const initSession = async () => {
            try {
                // First check server health
                const isHealthy = await checkServerHealth();
                if (!isHealthy) {
                    setError('Could not connect to server. Please check if the server is running.');
                    return;
                }

                // Then create a session
                console.log('Creating new session...');
                const response = await axios.post(`${SERVER_URL}/session`);
                if (response.data.success) {
                    const newSessionId = response.data.sessionId;
                    setSessionId(newSessionId);
                    addStatusMessage('system', `Session initialized: ${newSessionId}`);

                    // Initialize tools
                    console.log('Initializing tools...');
                    await axios.get(`${SERVER_URL}/init`);

                    // Take initial screenshot
                    requestScreenshot();
                } else {
                    setError(`Error initializing session: ${response.data.error}`);
                }
            } catch (err) {
                console.error('Session initialization error:', err);
                setError(`Failed to initialize session: ${err.message}`);
            }
        };

        initSession();

        // Cleanup on unmount
        return () => {
            if (messagePollingRef.current) clearTimeout(messagePollingRef.current);
            if (pollTimeoutRef.current) clearTimeout(pollTimeoutRef.current);
            if (streamSourceRef.current) streamSourceRef.current.close();
        };
    }, []);

    /**
     * Check if response is complete
     */
    const isResponseComplete = (messages) => {
        const lastAssistant = findLastMessage(messages, 'assistant');

        // No assistant message found
        if (!lastAssistant) {
            console.log('No assistant message found');
            return false;
        }

        // Explicit completion
        if (lastAssistant.finish_reason === 'stop') {
            console.log('Found explicit completion: finish_reason=stop');
            return true;
        }

        // Tool call completion
        if (lastAssistant.tool_calls && lastAssistant.tool_calls.length > 0) {
            const toolCallIds = lastAssistant.tool_calls.map(tc => tc.id);
            const toolResponses = messages.filter(m =>
                (m.role === 'tool' || m.role === 'function') &&
                toolCallIds.includes(m.tool_call_id)
            );

            console.log(`Tool calls: ${toolCallIds.length}, Tool responses: ${toolResponses.length}`);

            // Check if we have all tool responses and a follow-up message
            if (toolResponses.length === toolCallIds.length) {
                const lastToolIndex = Math.max(...toolResponses.map(
                    t => messages.findIndex(m => m.id === t.id)
                ));

                // Check for assistant message after tool responses
                const hasFollowUp = messages.some((m, i) =>
                    i > lastToolIndex && m.role === 'assistant'
                );

                if (hasFollowUp) {
                    console.log('Complete: all tool calls have responses and follow-up message');
                    return true;
                }

                console.log('All tool calls have responses but no follow-up message yet');
            }
        }

        // Content-based completion heuristics
        if (lastAssistant.content) {
            const hasSubstantialContent = lastAssistant.content.length > 50;
            const hasCompleteSentence = !!lastAssistant.content.match(/[.!?]\s*$/);
            const isComplete = hasSubstantialContent && hasCompleteSentence;

            console.log(`Content checks: substantial=${hasSubstantialContent}, complete sentence=${hasCompleteSentence}`);

            if (isComplete) {
                console.log('Complete: content appears complete');
                return true;
            }
        }

        console.log('Response not yet complete');
        return false;
    };

    /**
     * Find the last message with a specific role
     */
    const findLastMessage = (messages, role) => {
        for (let i = messages.length - 1; i >= 0; i--) {
            if (messages[i].role === role) return messages[i];
        }
        return null;
    };

    /**
     * Poll for message updates with throttling
     */
    const pollMessages = async (pollCount = 0) => {
        // Use ref value instead of closure value
        if (!sessionId || !loadingRef.current) {
            console.log(`Polling stopped: sessionId=${!!sessionId}, loading=${loadingRef.current}`);
            return;
        }

        console.log(`Polling for messages (attempt ${pollCount + 1}/${MAX_POLLS})`);

        // Stop polling after max attempts
        if (pollCount >= MAX_POLLS) {
            console.log(`Reached maximum polling attempts (${MAX_POLLS})`);
            setLoading(false);
            addStatusMessage('warning', 'Stopped polling after maximum attempts');
            return;
        }

        try {
            console.log(`Fetching messages from ${SERVER_URL}/messages/${sessionId}`);
            const response = await axios.get(
                `${SERVER_URL}/messages/${sessionId}?_t=${Date.now()}`,
                { timeout: 5000 }
            );

            if (response.data.success && response.data.messages) {
                const newMessages = response.data.messages;
                console.log(`Received ${newMessages.length} messages from server`);

                // Compare with current messages from ref to avoid closure issues
                const currentMessages = messagesRef.current;
                const hasNewMessages = newMessages.length > currentMessages.length;
                const hasUpdatedContent = newMessages.length === currentMessages.length &&
                    JSON.stringify(newMessages) !== JSON.stringify(currentMessages);

                console.log(`Has new messages: ${hasNewMessages}, Has updated content: ${hasUpdatedContent}`);

                // Update messages if there are changes
                if (hasNewMessages || hasUpdatedContent) {
                    setMessages(newMessages);

                    // Check if response is complete
                    const complete = isResponseComplete(newMessages);
                    console.log(`Response complete: ${complete}`);

                    if (complete) {
                        setLoading(false);
                        addStatusMessage('success', 'Response complete');
                        return;
                    }
                }
            } else {
                console.log('No messages or invalid response from server', response.data);
            }
        } catch (err) {
            console.error('Polling error:', err);
            addStatusMessage('error', `Polling error: ${err.message}`);
        }

        // Only continue polling if we're still in loading state
        if (!loadingRef.current) {
            console.log('Loading state is now false, stopping polling');
            return;
        }

        // Schedule next poll with throttling
        console.log(`Scheduling next poll in ${POLL_INTERVAL}ms`);
        if (messagePollingRef.current) {
            clearTimeout(messagePollingRef.current);
        }

        messagePollingRef.current = setTimeout(
            () => pollMessages(pollCount + 1),
            POLL_INTERVAL
        );
    };

    /**
     * Send a message to the API
     */
    const handleSendMessage = async (e) => {
        e.preventDefault();

        if (!inputValue.trim() || !sessionId) return;

        // Reset error and add user message
        setError(null);
        const userMessage = { role: 'user', content: inputValue };

        console.log('Adding user message and setting loading state');
        setMessages([...messages, userMessage]);
        setInputValue('');

        // Important: Set loading to true BEFORE starting to poll
        setLoading(true);

        try {
            console.log(`Sending message to ${SERVER_URL}/chat/${sessionId}`);
            const response = await axios.post(
                `${SERVER_URL}/chat/${sessionId}`,
                { message: inputValue },
                { timeout: 10000 }
            );

            if (response.data.success) {
                console.log('Message sent successfully, starting polling');
                addStatusMessage('info', 'Message sent, waiting for response...');

                // Start polling after a brief delay
                if (messagePollingRef.current) {
                    console.log('Clearing existing polling timeout');
                    clearTimeout(messagePollingRef.current);
                }

                console.log('Setting up new polling timeout');
                messagePollingRef.current = setTimeout(() => {
                    console.log('Starting initial poll');
                    pollMessages(0);
                }, 1000);
            } else {
                console.error('Error from server:', response.data.error);
                setError(`Error: ${response.data.error}`);
                setLoading(false);
            }
        } catch (err) {
            console.error('Error sending message:', err);
            // Handle session expiration
            if (err.response && err.response.status === 404) {
                handleSessionExpired();
            } else {
                setError(`Error sending message: ${err.message}`);
                setLoading(false);
            }
        }
    };

    /**
     * Handle an expired session
     */
    const handleSessionExpired = async () => {
        setError('Session expired. Creating a new session...');
        setSessionId(null);
        setLoading(false);

        try {
            const response = await axios.post(`${SERVER_URL}/session`);
            if (response.data.success) {
                setSessionId(response.data.sessionId);
                addStatusMessage('system', `New session created: ${response.data.sessionId}`);
                setError('Session recreated. Please send your message again.');
            } else {
                setError(`Failed to create new session: ${response.data.error}`);
            }
        } catch (err) {
            setError(`Failed to create new session: ${err.message}`);
        }
    };

    /**
     * Request a screenshot
     */
    const requestScreenshot = async () => {
        if (!sessionId) return;

        console.log('Requesting screenshot...');
        try {
            const params = { sessionId, _t: Date.now() };
            const response = await axios.get(`${SERVER_URL}/screenshot`, { params });

            if (response.data && response.data.image) {
                setBrowserImage(response.data.image);
                addStatusMessage('info', 'Screenshot updated');
            } else {
                console.log('Screenshot response:', response.data);
            }
        } catch (err) {
            console.error('Screenshot request failed:', err);
            addStatusMessage('warning', `Screenshot request failed: ${err.message}`);
        }
    };

    /**
     * Start browser stream
     */
    const startStream = () => {
        if (!sessionId || streaming) return;

        try {
            setStreamStatus('connecting');
            addStatusMessage('info', 'Starting browser stream...');

            // Close any existing stream
            if (streamSourceRef.current) {
                streamSourceRef.current.close();
            }

            // Create new EventSource connection
            const source = new EventSource(
                `${SERVER_URL}/browser-stream/${sessionId}?_t=${Date.now()}`
            );
            streamSourceRef.current = source;

            // Set up event handlers
            source.onmessage = (event) => {
                if (event.data && event.data.startsWith('data:image/')) {
                    setBrowserImage(event.data);
                    setStreamStatus('active');
                }
            };

            source.onopen = () => {
                setStreamStatus('active');
                setStreaming(true);
                addStatusMessage('success', 'Browser stream connected');
            };

            source.onerror = () => {
                setStreamStatus('error');
                addStatusMessage('error', 'Stream connection error');
                stopStream();
            };

        } catch (err) {
            addStatusMessage('error', `Failed to start stream: ${err.message}`);
            setStreamStatus('error');
        }
    };

    /**
     * Stop browser stream
     */
    const stopStream = () => {
        if (streamSourceRef.current) {
            try {
                streamSourceRef.current.close();
                streamSourceRef.current = null;

                // Try to notify server about disconnect
                axios.post(`${SERVER_URL}/stream-disconnect`, {
                    sessionId,
                    timestamp: Date.now()
                }).catch(() => { }); // Ignore errors

            } catch (err) {
                console.error('Error closing stream:', err);
            }
        }

        setStreaming(false);
        setStreamStatus('inactive');
        addStatusMessage('info', 'Stream connection closed');
    };

    /**
     * Scroll to bottom of messages
     */
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    // Toggle visibility of technical messages
    const toggleTechnicalMessages = () => setShowTechnicalMessages(!showTechnicalMessages);

    // Toggle visibility of preview section
    const togglePreview = () => {
        if (streaming && previewVisible) {
            stopStream();
        }
        setPreviewVisible(!previewVisible);
    };

    // Add special effect to handle loading state changes
    useEffect(() => {
        // When loading changes to true, start polling
        if (loading && sessionId) {
            console.log('Loading state changed to true, setting up polling');

            // Clear any existing polling
            if (messagePollingRef.current) {
                clearTimeout(messagePollingRef.current);
            }

            // Start fresh polling
            messagePollingRef.current = setTimeout(() => {
                console.log('Starting initial poll from loading effect');
                pollMessages(0);
            }, 1000);

            // Cleanup function
            return () => {
                if (messagePollingRef.current) {
                    console.log('Cleaning up polling timeout from loading effect');
                    clearTimeout(messagePollingRef.current);
                }
            };
        }
    }, [loading, sessionId]); // Deliberately exclude pollMessages to avoid infinite loops

    return (
        <div className="app-container">
            <header className="app-header">
                <h1>OpenAI MCP Client</h1>
                <button
                    className="toggle-preview-button"
                    onClick={togglePreview}
                >
                    {previewVisible ? 'Hide Preview' : 'Show Preview'}
                </button>
            </header>

            <main className="main-content">
                {/* Chat Section */}
                <div className="chat-section">
                    <div className="chat-header">
                        <h2>Chat</h2>
                        <button
                            className="toggle-technical-button"
                            onClick={toggleTechnicalMessages}
                        >
                            {showTechnicalMessages ? 'Hide Technical Details' : 'Show Technical Details'}
                        </button>
                    </div>

                    <div className="chat-container">
                        {messages
                            .filter(msg =>
                                ['user', 'assistant'].includes(msg.role) ||
                                (showTechnicalMessages && ['tool', 'system', 'function'].includes(msg.role))
                            )
                            .map((message, index) => (
                                <div key={index} className={`message ${message.role}`}>
                                    <div className="message-role">
                                        {message.role === 'function' ? 'tool-result' : message.role}
                                    </div>
                                    <div className="message-content">
                                        {message.role === 'function' || message.role === 'tool' ? (
                                            <pre className="tool-content">
                                                {typeof message.content === 'string'
                                                    ? message.content
                                                    : JSON.stringify(message.content, null, 2)}
                                            </pre>
                                        ) : (
                                            <div>{message.content}</div>
                                        )}

                                        {/* Display tool calls */}
                                        {message.tool_calls && (
                                            <div className="tool-calls">
                                                <div className="tool-call-header">Tool Calls:</div>
                                                {message.tool_calls.map((tool, toolIndex) => (
                                                    <div key={toolIndex} className="tool-call">
                                                        <div className="tool-name">
                                                            {tool.function?.name || 'Unknown Tool'}
                                                        </div>
                                                        <pre className="tool-args">
                                                            {tool.function?.arguments || '{}'}
                                                        </pre>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}

                        {/* Error message */}
                        {error && (
                            <div className="message error">
                                <div className="message-role">Error</div>
                                <div className="message-content">{error}</div>
                            </div>
                        )}

                        {/* Loading indicator */}
                        {loading && (
                            <div className="message loading">
                                <div className="message-content">
                                    <div className="loading-spinner"></div>
                                </div>
                            </div>
                        )}

                        <div ref={messagesEndRef} />
                    </div>

                    {/* Message input form */}
                    <form className="input-container" onSubmit={handleSendMessage}>
                        <input
                            type="text"
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            placeholder="Type your message..."
                            className="message-input"
                            disabled={loading || !sessionId}
                        />
                        <button
                            type="submit"
                            className="send-button"
                            disabled={loading || !sessionId || !inputValue.trim()}
                        >
                            Send
                        </button>
                    </form>
                </div>

                {/* Preview Section */}
                {previewVisible && (
                    <div className="preview-section">
                        <h2 className="preview-title">
                            Browser Preview
                            <div className="preview-controls">
                                {streaming ? (
                                    <button
                                        onClick={stopStream}
                                        className="stream-button stop"
                                        disabled={!sessionId}
                                    >
                                        Stop Stream
                                    </button>
                                ) : (
                                    <button
                                        onClick={startStream}
                                        className="stream-button start"
                                        disabled={!sessionId}
                                    >
                                        Start Stream
                                    </button>
                                )}
                                <button
                                    onClick={requestScreenshot}
                                    className="refresh-preview-button"
                                    disabled={!sessionId || streaming}
                                >
                                    Take Screenshot
                                </button>
                            </div>
                        </h2>

                        {/* Stream status indicator */}
                        <div className={`stream-status ${streamStatus} ${streaming ? 'pulsing' : ''}`}>
                            {streamStatus === 'waiting' ? 'Ready' :
                                streamStatus === 'connecting' ? 'Connecting...' :
                                    streamStatus === 'active' ? 'Stream active' :
                                        streamStatus === 'error' ? 'Stream error' :
                                            streamStatus.charAt(0).toUpperCase() + streamStatus.slice(1)}
                        </div>

                        {/* Browser preview image */}
                        <div className="browser-preview">
                            {browserImage ? (
                                <img
                                    src={browserImage}
                                    alt="Browser preview"
                                    className="browser-image"
                                    title={streaming ? "Live stream" : "Static screenshot"}
                                />
                            ) : (
                                <div className="no-preview">
                                    No browser activity yet
                                </div>
                            )}
                        </div>

                        {/* Status log */}
                        <div className="status-log">
                            <h3>Status Log</h3>
                            <div className="status-messages">
                                {statusMessages.length === 0 ? (
                                    <div className="status-message info">
                                        <span className="status-time">--:--:--</span>
                                        <span className="status-text">Waiting for activity...</span>
                                    </div>
                                ) : (
                                    statusMessages.map((status, index) => (
                                        <div key={index} className={`status-message ${status.type}`}>
                                            <span className="status-time">{status.time}</span>
                                            <span className="status-text">{status.text}</span>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
}

export default App;
